            applyOperator();
          }
          operators.pop(); // Remove the '('
        } else {
          throw new Error('Invalid token');
        }
      }

      while (operators.length) {
        applyOperator();
      }

      return values.pop();
    } catch (error) {
      throw new Error('Invalid expression');
    }
  } else {
